import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100KnockoutEnergyTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static CardInstance energy(ServerMatch m,String type,UUID host){return StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_"+type+"_energy",host);}
    static void lethal(ServerMatch m){var victim=m.activePokemonView(A);m.placeDamageCountersByEffect(A,A,victim.pokemonId(),(victim.hitPoints()-10)/10);for(int i=0;i<2;i++)StarterDeck100EnergyTest.attach(m,A,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());m.endTurn(A);m.attack(B,"leaf-drain");}
    static void accept(ServerMatch m,boolean use){var p=m.triggerOrderPrompt();check(p!=null&&p.optionalDecision()&&p.choosingPlayer().equals(A),"KO owner optional choice absent");m.decideTriggeredEffect(A,p.id(),use);}
    static void choose(ServerMatch m,List<CardInstance> cards){var p=m.effectCardPrompt(A);check(p!=null,"missing public Energy choice");TopDeckLookTest.rejects(()->m.submitEffectCards(B,p.resolutionId(),p.step(),cards.stream().map(CardInstance::instanceId).toList()));m.submitEffectCards(A,p.resolutionId(),p.step(),cards.stream().map(CardInstance::instanceId).toList());TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),cards.stream().map(CardInstance::instanceId).toList()));check(!m.hasPendingAttachmentTarget(),"fixed source asked player to choose another host");}
    public static void main(String[] args){for(boolean use:List.of(false,true)){share(use);kingdra(use);}noCounterTrigger();sameHost();multiple();waterDamage();System.out.println("StarterDeck100KnockoutEnergyTest passed: captured pre-KO Energy, fixed source destination, exact filters, optional decisions, shared remaining pool and cause boundaries");}
    static void share(boolean use){var m=StarterDeck100PokemonTest.game(1,id(383),id(413));var source=m.activePokemonView(A).pokemonId();var host=m.benchPokemonView(A).getFirst().pokemonId();m.playTrainer(A,StarterDeck100PokemonTest.hand(m,id(383)).instanceId(),host);var e=energy(m,"grass",source);var special=StarterDeck100EnergyTest.attach(m,A,A,id(413),source);lethal(m);check(m.publicView().get(B).prizeCount()==6,"prizes awarded before transfer");accept(m,use);if(use){var p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(e)),"Exp Share included Special Energy");TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(special.instanceId())));TopDeckLookTest.rejects(()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));choose(m,List.of(e));}StarterDeck100CombatTest.settleKnockouts(m);check(m.activePokemonView(A).pokemonId().equals(host)&&m.activePokemonView(A).attachedEnergyIds().contains(e.instanceId())==use,"Exp Share wrong destination or decline");check(m.privateView(A).discard().contains(special)&&m.publicView().get(B).prizeCount()==4,"KO did not discard remainder or award2");}
    static void kingdra(boolean use){var m=StarterDeck100PokemonTest.game(84);UUID host=m.activePokemonView(A).pokemonId(),source=m.benchPokemonView(A).getFirst().pokemonId();m.switchActiveByEffect(A,A,source);var w1=energy(m,"water",source);var w2=energy(m,"water",source);var grass=energy(m,"grass",source);lethal(m);accept(m,use);if(use){check(m.effectCardPrompt(A).candidates().size()==2&&!m.effectCardPrompt(A).candidates().contains(grass),"Kingdra did not filter current Water provision");choose(m,List.of(w1,w2));}StarterDeck100CombatTest.settleKnockouts(m);check(m.activePokemonView(A).pokemonId().equals(host)&&m.activePokemonView(A).attachedEnergyIds().size()==(use?2:0),"Kingdra failed multi-card fixed transfer");check(m.privateView(A).discard().contains(grass),"unselected Energy not discarded on KO");}
    static void noCounterTrigger(){for(int n:List.of(1,84)){var m=StarterDeck100PokemonTest.game(n,id(383));UUID host=m.activePokemonView(A).pokemonId(),source=m.benchPokemonView(A).getFirst().pokemonId();if(n==1)m.playTrainer(A,StarterDeck100PokemonTest.hand(m,id(383)).instanceId(),host);m.switchActiveByEffect(A,A,source);energy(m,n==84?"water":"grass",source);m.placeDamageCountersByEffect(A,A,source,50);check(m.triggerOrderPrompt()==null,"counter KO triggered attack-damage listener");StarterDeck100CombatTest.settleKnockouts(m);check(m.activePokemonView(A).attachedEnergyIds().isEmpty(),"counter KO transferred Energy");}}
    static void sameHost(){var m=StarterDeck100PokemonTest.game(1,id(383));var source=m.activePokemonView(A).pokemonId();m.playTrainer(A,StarterDeck100PokemonTest.hand(m,id(383)).instanceId(),source);energy(m,"grass",source);lethal(m);if(m.triggerOrderPrompt()!=null)accept(m,true);check(!m.hasPendingCardSelection()&&!m.hasPendingEffectChoice(),"source equals destination created an unfinishable transfer");StarterDeck100CombatTest.settleKnockouts(m);}
    static void multiple(){var m=StarterDeck100PokemonTest.game(1,id(383));var source=m.activePokemonView(A).pokemonId();var extra=StarterDeck100PokemonTest.hand(m,id(1));m.playBasicPokemonToBench(A,extra.instanceId());var hosts=m.benchPokemonView(A).stream().map(p->p.pokemonId()).toList();for(var host:hosts)m.playTrainer(A,StarterDeck100PokemonTest.hand(m,id(383)).instanceId(),host);var e=energy(m,"grass",source);lethal(m);var order=m.triggerOrderPrompt();check(order!=null&&!order.optionalDecision()&&order.entries().size()==2,"two tools did not share KO ordering");m.chooseTriggeredEffect(order.choosingPlayer(),order.id(),order.entries().getFirst().id());accept(m,true);choose(m,List.of(e));while(m.triggerOrderPrompt()!=null)accept(m,true);StarterDeck100CombatTest.settleKnockouts(m);long transferred=m.activePokemonView(A).attachedEnergyIds().size()+m.benchPokemonView(A).stream().mapToLong(p->p.attachedEnergyIds().size()).sum();check(transferred==1,"second tool duplicated already moved Energy");}
    static void waterDamage(){var m=StarterDeck100PokemonTest.game(84);var host=m.activePokemonView(A).pokemonId();energy(m,"water",host);energy(m,"water",host);energy(m,"grass",host);m.attack(A,"aqua-burst");check(m.lastAttack().finalDamage()==80,"Aqua Burst not40 per Water unit");}
}
